namespace Ff7.Accessibility.Reloaded;

/// <summary>
/// Exact description-cue identities for field scripts whose loaded prefix is not the English
/// stock prefix: the official French, German, Spanish and Japanese archives and the Bunio Polish
/// V1.05 fan translation. A row authorizes one English catalog cue at the coordinates where that
/// exact loaded prefix runs the same native instruction; any other prefix, entity, slot, byte or
/// opcode stays silent, and the English cue keeps its key, text, recurring group and history.
///
/// <para>The rows are generated by tools/LocalizedDescriptionCueAligner from the installed
/// archives: a forced alignment of each whole slot, never an offset search, a nearby match or a
/// runtime guess. The evidence and the one exclusion are in
/// docs/localized-description-triggers-20261125.md.</para>
///
/// <para>Malformed or stale rows are dropped individually and counted, never thrown at runtime:
/// a broken row may silence its own cue, but it can never take English descriptions down with it.
/// The regression suite requires zero dropped rows and the generated catalog fingerprint.</para>
/// </summary>
public static partial class LocalizedFieldDescriptionCueManifest
{
    private static readonly IReadOnlySet<string> Languages = new HashSet<string>(StringComparer.Ordinal) { "fr", "de", "es", "ja", "pl" };

    public static bool IsReviewedIdentity(LoadedFieldScriptIdentity identity) => Find(identity) is not null;

    /// <summary>The reviewed archives (language codes) that load exactly this prefix, or none.</summary>
    public static IReadOnlyList<string> ResolveLanguages(LoadedFieldScriptIdentity identity) =>
        Find(identity)?.Languages ?? [];

    /// <summary>Maps a reviewed native event of a localized prefix back to the English catalog's key.</summary>
    public static FieldCutsceneDescriptionKey? ResolveCanonicalCueKey(FieldScriptContext context, LoadedFieldScriptIdentity identity) =>
        context.FieldId == identity.FieldId && Find(identity) is { } reviewed &&
        reviewed.CanonicalKeys.TryGetValue(new(context.FieldId, context.EntityId, context.ScriptId, context.ByteIndex), out var canonical)
            ? canonical
            : null;

    /// <summary>The English cues this exact prefix runs, at the coordinates it runs them.</summary>
    internal static IReadOnlyList<FieldCutsceneDescriptionCue> CreateDescriptions(LoadedFieldScriptIdentity identity) =>
        Find(identity)?.Cues ?? [];

    /// <summary>
    /// Whether this exact field 767 prefix keeps the stock creature warning: MESSAGE window 1
    /// dialog 10 at entity 3 slot 6 byte 44, the same entity list, and every model-assigning
    /// CHAR and PC, so FieldCreatureApproachReader's creature model slot 8 still holds.
    /// </summary>
    internal static bool HasReviewedCreatureWarning(LoadedFieldScriptIdentity identity) =>
        identity.FieldId == 767 && Find(identity)?.CreatureWarning == true;

    internal static IReadOnlyCollection<ReviewedLocalizedIdentity> ReviewedIdentities => Data.Identities;

    internal static IReadOnlyList<string> InvalidRows => Data.InvalidRows;

    private static ReviewedLocalizedIdentity? Find(LoadedFieldScriptIdentity identity) =>
        identity.ScriptPrefixSha256 is { Length: 64 } prefix &&
        Data.ByField.TryGetValue(identity.FieldId, out var prefixes) &&
        prefixes.TryGetValue(prefix, out var reviewed)
            ? reviewed
            : null;

    private static ManifestData Data => Holder.Value;

    private static class Holder
    {
        internal static readonly ManifestData Value = Read(RawIdentities);
    }

    internal static ManifestData Read(string raw)
    {
        var catalog = FieldCutsceneDescriptionCatalog.CreateEarlyGameDescriptions()
            .GroupBy(cue => cue.Key)
            .ToDictionary(group => group.Key, group => group.First());
        var invalid = new List<string>();
        var byField = new Dictionary<int, Dictionary<string, ReviewedLocalizedIdentity>>();
        IdentityBuilder? current = null;
        void Close()
        {
            if (current is null) return;
            var built = current.Build();
            if (!byField.TryGetValue(built.FieldId, out var prefixes))
                byField[built.FieldId] = prefixes = new Dictionary<string, ReviewedLocalizedIdentity>(StringComparer.OrdinalIgnoreCase);
            if (!prefixes.TryAdd(built.PrefixSha256, built)) invalid.Add($"duplicate identity {built.FieldId},{built.PrefixSha256}");
            current = null;
        }

        foreach (var line in raw.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
        {
            if (line[0] == '@')
            {
                Close();
                var header = line[1..].Split(',');
                if (header.Length == 4 && int.TryParse(header[0], out var field) && field is >= 0 and <= ushort.MaxValue &&
                    header[1].Length == 64 && header[1].All(Uri.IsHexDigit) &&
                    header[2].Split('|') is { Length: > 0 } codes && codes.All(Languages.Contains) &&
                    header[3] is "0" or "1")
                    current = new IdentityBuilder(field, header[1].ToUpperInvariant(), codes, header[3] == "1");
                else
                    invalid.Add("identity " + line);
                continue;
            }

            if (current is null)
            {
                invalid.Add("row outside an identity " + line);
                continue;
            }

            var exclusion = line[0] == '!';
            var values = (exclusion ? line[1..] : line).Split(',');
            var numbers = values.Take(exclusion ? 4 : values.Length).Select(v => int.TryParse(v, out var n) ? n : -1).ToArray();
            if (numbers.Any(n => n < 0) || (exclusion ? values.Length != 5 : numbers.Length is not (4 or 7)))
            {
                invalid.Add($"row {current.FieldId}: {line}");
                continue;
            }

            var key = new FieldCutsceneDescriptionKey(current.FieldId, numbers[0], numbers[1], numbers[2]);
            if (!catalog.TryGetValue(key, out var cue) || cue.Opcode != numbers[3])
            {
                invalid.Add($"row {current.FieldId}: {line} has no English catalog cue with that opcode");
                continue;
            }

            if (exclusion)
            {
                if (!current.Exclude(key)) invalid.Add($"row {current.FieldId}: {line} repeats an English cue");
                continue;
            }

            var target = numbers.Length == 7 ? new FieldCutsceneDescriptionKey(current.FieldId, numbers[4], numbers[5], numbers[6]) : key;
            if (target.EntityId > byte.MaxValue || target.ScriptId >= FieldScriptContextReader.ScriptOffsetsPerEntity ||
                target.ByteIndex > ushort.MaxValue || !current.Authorize(cue, target))
                invalid.Add($"row {current.FieldId}: {line} conflicts with another row");
        }

        Close();
        return new ManifestData(byField, invalid);
    }

    internal sealed record ManifestData(
        IReadOnlyDictionary<int, Dictionary<string, ReviewedLocalizedIdentity>> ByField,
        IReadOnlyList<string> InvalidRows)
    {
        public IReadOnlyCollection<ReviewedLocalizedIdentity> Identities { get; } =
            ByField.Values.SelectMany(prefixes => prefixes.Values).ToArray();
    }

    private sealed class IdentityBuilder(int fieldId, string prefixSha256, string[] languages, bool creatureWarning)
    {
        private readonly Dictionary<FieldCutsceneDescriptionKey, FieldCutsceneDescriptionCue> byTarget = new();
        private readonly Dictionary<FieldCutsceneDescriptionKey, FieldCutsceneDescriptionKey> canonical = new();
        private readonly HashSet<FieldCutsceneDescriptionKey> english = new();
        private readonly HashSet<FieldCutsceneDescriptionKey> excluded = new();

        public int FieldId { get; } = fieldId;

        public bool Authorize(FieldCutsceneDescriptionCue cue, FieldCutsceneDescriptionKey target)
        {
            if (excluded.Contains(cue.Key) || !english.Add(cue.Key) || byTarget.ContainsKey(target)) return false;
            byTarget[target] = cue with { EntityId = target.EntityId, ScriptId = target.ScriptId, ByteIndex = target.ByteIndex };
            canonical[target] = cue.Key;
            return true;
        }

        public bool Exclude(FieldCutsceneDescriptionKey key) => !english.Contains(key) && excluded.Add(key);

        public ReviewedLocalizedIdentity Build() =>
            new(FieldId, prefixSha256, languages, creatureWarning, byTarget.Values.ToArray(), canonical, excluded.ToArray());
    }
}

/// <summary>
/// The loaded-script identity decisions both runtimes make for field descriptions and film
/// anchors, in one place so the x86 host (Mod.cs) and the x64 coordinator cannot drift apart.
/// </summary>
public static class LocalizedFieldScriptIdentityPolicy
{
    /// <summary>The entity, slot and byte of <see cref="FilmAnchor"/> when it names no anchor.</summary>
    public const int NoAnchor = -1;

    /// <summary>
    /// Whether field descriptions may be delivered for this loaded script: a reviewed navigation
    /// identity (English or official localized stock, Echo-S, Postscript) or an exact reviewed
    /// localized description identity, which is how the Bunio Polish V1.05 prefixes are known.
    /// Any other prefix stays silent.
    /// </summary>
    public static bool AllowsDescriptions(LoadedFieldScriptIdentity identity) =>
        WholeGameEchoNavigationManifest.ResolveVariant(identity) != SupportedFieldScriptVariant.Unknown ||
        LocalizedFieldDescriptionCueManifest.IsReviewedIdentity(identity);

    /// <summary>
    /// Whether a host may keep this identity for the field instead of re-reading and re-hashing the
    /// loaded script: every reviewed variant, the Echo-S disclaimer, and an exact reviewed localized
    /// prefix. An unknown prefix is always read again.
    /// </summary>
    public static bool IsReviewedLoadedIdentity(LoadedFieldScriptIdentity identity) =>
        EchoSCompatibilityManifest.ResolveVariant(identity) != SupportedFieldScriptVariant.Unknown ||
        EchoSCompatibilityManifest.IsSupportedDisclaimer(identity) ||
        LocalizedFieldDescriptionCueManifest.IsReviewedIdentity(identity);

    /// <summary>
    /// The coordinates <see cref="FieldMovieNarrationPolicy"/> is asked about for a native event or a
    /// queued cue. A reviewed localized prefix answers with the English anchor of the instruction it
    /// runs there - Polish V1.05 starts the nvlmk film at zcoal_2 byte 101 and zcoal_3 byte 70, where
    /// English uses 104 and 90 - and with no anchor for any position it does not map, because its raw
    /// offsets are not English offsets. Stock, Echo-S, Postscript, unknown and unreadable identities
    /// keep the raw coordinates they always used.
    /// </summary>
    public static FieldCutsceneDescriptionKey FilmAnchor(FieldScriptContext context, LoadedFieldScriptIdentity? identity)
    {
        var raw = new FieldCutsceneDescriptionKey(context.FieldId, context.EntityId, context.ScriptId, context.ByteIndex);
        if (identity is not { } loaded || loaded.FieldId != context.FieldId ||
            EchoSCompatibilityManifest.ResolveVariant(loaded) != SupportedFieldScriptVariant.Unknown ||
            !LocalizedFieldDescriptionCueManifest.IsReviewedIdentity(loaded))
            return raw;
        return LocalizedFieldDescriptionCueManifest.ResolveCanonicalCueKey(context, loaded) ??
               new FieldCutsceneDescriptionKey(context.FieldId, NoAnchor, NoAnchor, NoAnchor);
    }
}

/// <summary>One reviewed exact loaded prefix and the cues it runs.</summary>
internal sealed record ReviewedLocalizedIdentity(
    int FieldId,
    string PrefixSha256,
    IReadOnlyList<string> Languages,
    bool CreatureWarning,
    IReadOnlyList<FieldCutsceneDescriptionCue> Cues,
    IReadOnlyDictionary<FieldCutsceneDescriptionKey, FieldCutsceneDescriptionKey> CanonicalKeys,
    IReadOnlyList<FieldCutsceneDescriptionKey> ExcludedEnglishKeys);

/// <summary>
/// The localized catalog of whichever reviewed localized prefix is loaded. One
/// <see cref="FieldCutsceneDescriptionTracker"/> per bound identity keeps the stock tracker's
/// once-per-visit, opcode and recurring-group rules on the coordinates the loaded script runs.
/// </summary>
public sealed class LocalizedFieldCutsceneDescriptionTracker
{
    private readonly object sync = new();
    private FieldCutsceneDescriptionTracker? tracker;
    private int boundFieldId = -1;
    private string? boundPrefix;

    public FieldCutsceneDescriptionCue? Observe(FieldScriptContext context, LoadedFieldScriptIdentity identity)
    {
        if (identity.FieldId != context.FieldId) return null;
        var cues = LocalizedFieldDescriptionCueManifest.CreateDescriptions(identity);
        if (cues.Count == 0) return null;
        FieldCutsceneDescriptionTracker current;
        lock (sync)
        {
            if (tracker is null || boundFieldId != identity.FieldId ||
                !string.Equals(boundPrefix, identity.ScriptPrefixSha256, StringComparison.OrdinalIgnoreCase))
            {
                tracker = new FieldCutsceneDescriptionTracker(cues);
                boundFieldId = identity.FieldId;
                boundPrefix = identity.ScriptPrefixSha256;
            }

            current = tracker;
        }

        return current.Observe(context);
    }

    public void Reset()
    {
        lock (sync)
        {
            tracker = null;
            boundFieldId = -1;
            boundPrefix = null;
        }
    }
}
